module down_counter_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg [3:0] init_value;
    reg load;
    reg rst_n;
    wire [3:0] count;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    down_counter dut (
        .clk(clk),
        .init_value(init_value),
        .load(load),
        .rst_n(rst_n),
        .count(count)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            rst_n = 0;
            load = 0;
            init_value = 0;
            @(posedge clk);
            #1;
            rst_n = 1;
            @(posedge clk);
            #1;
        end
        endtask
    task testcase001;

        begin
            test_num = 1;
            $display("Testcase %03d: Basic decrement from 10 to 7", test_num);
            reset_dut();


            init_value = 4'd10;
            load = 1;
            @(posedge clk);
            #1 load = 0;


            repeat(3) @(posedge clk);
            #1;

            #1;


            check_outputs(4'd7);
        end
        endtask

    task testcase002;

        begin
            test_num = 2;
            $display("Testcase %03d: Wrap around from 0 back to init_value (3)", test_num);
            reset_dut();


            init_value = 4'd3;
            load = 1;
            @(posedge clk);
            #1 load = 0;



            repeat(4) @(posedge clk);
            #1;

            #1;


            check_outputs(4'd3);
        end
        endtask

    task testcase003;

        begin
            test_num = 3;
            $display("Testcase %03d: Reaching zero from 5", test_num);
            reset_dut();

            init_value = 4'd5;
            load = 1;
            @(posedge clk);
            #1 load = 0;


            repeat(5) @(posedge clk);
            #1;

            #1;


            check_outputs(4'd0);
        end
        endtask

    task testcase004;

        begin
            test_num = 4;
            $display("Testcase %03d: Load new value mid-count", test_num);
            reset_dut();


            init_value = 4'd15;
            load = 1;
            @(posedge clk);
            #1 load = 0;

            repeat(2) @(posedge clk);


            #1;
            init_value = 4'd4;
            load = 1;
            @(posedge clk);
            #1 load = 0;


            @(posedge clk);
            #1;

            #1;


            check_outputs(4'd3);
        end
        endtask

    task testcase005;

        begin
            test_num = 5;
            $display("Testcase %03d: Rapid wrap-around with init_value=1", test_num);
            reset_dut();

            init_value = 4'd1;
            load = 1;
            @(posedge clk);
            #1 load = 0;




            repeat(3) @(posedge clk);
            #1;

            #1;


            check_outputs(4'd0);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("down_counter Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [3:0] expected_count;
        begin
            if (expected_count === (expected_count ^ count ^ expected_count)) begin
                $display("PASS");
                $display("  Outputs: count=%h",
                         count);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: count=%h",
                         expected_count);
                $display("  Got:      count=%h",
                         count);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,clk, init_value, load, rst_n, count);
    end

endmodule

