module DAC_Controller (
    input [15:0] dac_input,
    input clk,
    output reg ready
);
    parameter STABLE_CYCLES = 3;
    reg [1:0] counter = 0;
    reg [15:0] last_input = 0;

    always @(posedge clk) begin
        if (dac_input == last_input) begin
            if (counter < STABLE_CYCLES - 1) begin
                counter <= counter + 1;
            end else begin
                ready <= 1;
            end
        end else begin
            counter <= 0;
            ready <= 0;
        end
        last_input <= dac_input;
    end
endmodule

