module watchdog_timer_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg reset_n;
    wire reset_indicator;
    wire timeout;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    watchdog_timer dut (
        .clk(clk),
        .reset_n(reset_n),
        .reset_indicator(reset_indicator),
        .timeout(timeout)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

    begin
        reset_n = 1'b0;
        repeat(3) @(posedge clk);
        #1;
        reset_n = 1'b1;
        @(posedge clk);
        #1;
    end
        endtask
    task testcase001;

    begin
        test_num = 1;
        $display("Testcase %0d: Verifying post-reset state...", test_num);
        reset_dut();

        #1;


        check_outputs(1'b0, 1'b0);
    end
        endtask

    task testcase002;

    begin
        test_num = 2;
        $display("Testcase %0d: Running for 8 cycles to trigger timeout...", test_num);
        reset_dut();

        repeat(8) @(posedge clk);
        #1;
        #1;

        check_outputs(1'b0, 1'b1);
    end
        endtask

    task testcase003;

    begin
        test_num = 3;
        $display("Testcase %0d: Resetting halfway through count to prevent timeout...", test_num);
        reset_dut();
        repeat(5) @(posedge clk);
        reset_n = 1'b0;
        repeat(1) @(posedge clk);
        #1;
        reset_n = 1'b1;
        repeat(5) @(posedge clk);
        #1;

        #1;


        check_outputs(1'b0, 1'b0);
    end
        endtask

    task testcase004;

    begin
        test_num = 4;
        $display("Testcase %0d: Clearing timeout via reset...", test_num);
        reset_dut();
        repeat(8) @(posedge clk);
        #1;

        if (timeout !== 1'b1) $display("  Wait: Timeout did not trigger as expected.");

        reset_n = 1'b0;
        repeat(2) @(posedge clk);
        #1;
        reset_n = 1'b1;
        repeat(1) @(posedge clk);
        #1;
        #1;

        check_outputs(1'b0, 1'b0);
    end
        endtask

    task testcase005;

    begin
        test_num = 5;
        $display("Testcase %0d: Holding reset active for extended period...", test_num);
        reset_dut();
        reset_n = 1'b0;
        repeat(12) @(posedge clk);
        #1;

        #1;


        check_outputs(1'b1, 1'b0);
    end
        endtask

    task testcase006;

    begin
        test_num = 6;
        $display("Testcase %0d: Checking if timeout persists after limit...", test_num);
        reset_dut();
        repeat(15) @(posedge clk);
        #1;
        #1;

        check_outputs(1'b0, 1'b1);
    end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("watchdog_timer Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input expected_reset_indicator;
        input expected_timeout;
        begin
            if (expected_reset_indicator === (expected_reset_indicator ^ reset_indicator ^ expected_reset_indicator) &&
                expected_timeout === (expected_timeout ^ timeout ^ expected_timeout)) begin
                $display("PASS");
                $display("  Outputs: reset_indicator=%b, timeout=%b",
                         reset_indicator, timeout);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: reset_indicator=%b, timeout=%b",
                         expected_reset_indicator, expected_timeout);
                $display("  Got:      reset_indicator=%b, timeout=%b",
                         reset_indicator, timeout);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,clk, reset_n, reset_indicator, timeout);
    end

endmodule

