module edge_detector #(parameter PULSE_WIDTH = 4) (  
    input clk,  
    input rst,  
    input signal_in,  
    output reg pulse_out  
);  
    reg [1:0] state;  
    reg [3:0] pulse_counter;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= 2'b00;  
            pulse_out <= 1'b0;  
            pulse_counter <= 4'b0000;  
        end  
        else begin  
            case (state)  
                2'b00: begin // Idle state  
                    if (signal_in) begin  
                        pulse_out <= 1'b1;  
                        pulse_counter <= PULSE_WIDTH;  
                        state <= 2'b01;  
                    end  
                end  
                2'b01: begin // Pulse active  
                    if (pulse_counter > 0) begin  
                        pulse_counter <= pulse_counter - 1;  
                    end  
                    else begin  
                        pulse_out <= 1'b0;  
                        state <= 2'b00;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

