module watchdog_timer (  
    input wire clk,  
    input wire reset,  
    input wire timeout_signal,  
    output reg timeout  
);  
    parameter TIMEOUT_PERIOD = 8'd100; // timeout after 100 clock cycles  
    reg [7:0] counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 8'b0;  
            timeout <= 1'b0;  
        end else if (timeout_signal) begin  
            counter <= 8'b0;  
            timeout <= 1'b0;  
        end else if (counter < TIMEOUT_PERIOD) begin  
            counter <= counter + 1;  
            timeout <= 1'b0;  
        end else begin  
            timeout <= 1'b1;  
        end  
    end  
endmodule

