module sliding_window_controller (  
    input clk,  
    input reset,  
    input send,  
    input ack,  
    output reg [3:0] current_frame,  
    output reg [1:0] state  
);  
    parameter IDLE = 2'b00,  
              SEND = 2'b01,  
              WAIT_ACK = 2'b10;  
    parameter WINDOW_SIZE = 4;  

    reg [3:0] frame_number;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            frame_number <= 0;  
            current_frame <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (send) begin  
                        current_frame <= frame_number;  
                        state <= SEND;  
                    end  
                end  
                SEND: begin  
                    if (ack) begin  
                        frame_number <= (frame_number + 1) % WINDOW_SIZE;  
                        state <= WAIT_ACK;  
                    end  
                end  
                WAIT_ACK: begin  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

