        .clk(clk),
        .data_in(data_in),
        .rst(rst),
        .valid(valid),
        .checksum(checksum),
        .ready(ready)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            rst = 1;
            valid = 0;
            data_in = 0;
            @(posedge clk);
            #1 rst = 0;
