module uart_transmitter (
    input wire clk,
    input wire rst,
    input wire start,
    input wire [7:0] data_in,
    output reg tx,
    output reg busy
);

    parameter BAUD_RATE_DIV = 16; // For simulation; adjust for actual baud rate
    parameter DATA_BITS = 8;

    reg [3:0] state;
    reg [3:0] bit_count;
    reg [7:0] shift_reg;
    reg [3:0] clk_div;

    localparam IDLE = 4'd0;
    localparam START_BIT = 4'd1;
    localparam DATA_BITS_SEND = 4'd2;
    localparam STOP_BIT = 4'd3;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx <= 1; // Idle state for UART is high
            busy <= 0;
            state <= IDLE;
            bit_count <= 0;
            clk_div <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start && !busy) begin
                        busy <= 1;
                        shift_reg <= data_in;
                        tx <= 0; // Start bit
                        state <= START_BIT;
                        clk_div <= 0;
                        bit_count <= 0;
                    end
                end

                START_BIT: begin
                    if (clk_div == BAUD_RATE_DIV - 1) begin
                        clk_div <= 0;
                        state <= DATA_BITS_SEND;
                    end else begin
                        clk_div <= clk_div + 1;
                    end
                end

                DATA_BITS_SEND: begin
                    if (clk_div == BAUD_RATE_DIV - 1) begin
                        clk_div <= 0;
                        tx <= shift_reg[0]; // Send the least significant bit
                        shift_reg <= shift_reg >> 1; // Shift right
                        bit_count <= bit_count + 1;
                        if (bit_count == DATA_BITS - 1) begin
                            state <= STOP_BIT;
                        end
                    end else begin
                        clk_div <= clk_div + 1;
                    end
                end

                STOP_BIT: begin
                    if (clk_div == BAUD_RATE_DIV - 1) begin
                        clk_div <= 0;
                        tx <= 1; // Stop bit
                        busy <= 0;
                        state <= IDLE;
                    end else begin
                        clk_div <= clk_div + 1;
                    end
                end
            endcase
        end
    end
endmodule

