module binary_counter(  
    input wire clk,  
    input wire enable,  
    input wire reset,  
    output reg [3:0] count  
);  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            count <= 4'b0000;  
        end else if (enable) begin  
            if (count == 4'b1111)  
                count <= 4'b0000;  
            else  
                count <= count + 1;  
        end  
    end  
endmodule

