module stop_and_wait_arq #(parameter DATA_WIDTH = 8) (  
    input clk,  
    input rst,  
    input [DATA_WIDTH-1:0] data_in,  
    output reg ack_out,  
    output reg [DATA_WIDTH-1:0] data_out  
);  

    reg [1:0] state;  
    reg [1:0] next_state;  
    reg [DATA_WIDTH-1:0] sent_data;  

    localparam IDLE = 2'b00, SEND = 2'b01, WAIT_ACK = 2'b10;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            ack_out <= 0;  
            data_out <= 0;  
        end else begin  
            state <= next_state;  
            if (state == SEND) begin  
                data_out <= sent_data;  
            end  
        end  
    end  

    always @(*) begin  
        next_state = state;  
        ack_out = 0;  
        case (state)  
            IDLE: begin  
                sent_data = data_in;  
                next_state = SEND;  
            end  
            SEND: begin  
                ack_out = 1;  // Simulating sending the ack after sending data  
                next_state = WAIT_ACK;  
            end  
            WAIT_ACK: begin  
                // Wait for an ack signal (simulated here)  
                next_state = IDLE;  
            end  
        endcase  
    end  
endmodule

