        if (reset) begin
            frequency <= FREQ_LOW;
            voltage <= VOLT_LOW;
        end else begin
            if (load > LOAD_THRESHOLD) begin
                // High load, increase frequency and voltage
                frequency <= FREQ_HIGH;
                voltage <= VOLT_HIGH;
            end else begin
                // Low load, decrease frequency and voltage
                frequency <= FREQ_MED;
                voltage <= VOLT_MED;
            end
        end
    end
endmodule

