module fractional_n_pll (
    input wire clk_ref,          // Reference clock input
    input wire reset,           // Asynchronous reset
    input wire [7:0] frac_div,  // Fractional divider value
    output reg clk_out          // Output clock
);

reg [15:0] counter;            // Counter for generating output clock
reg [15:0] frac_counter;       // Fractional counter

always @(posedge clk_ref or posedge reset) begin
    if (reset) begin
        counter <= 0;
        frac_counter <= 0;
        clk_out <= 0;
    end else begin
        if (counter < frac_div) begin
            counter <= counter + 1;
        end else begin
            counter <= 0;
            clk_out <= ~clk_out; // Toggle the output clock
        end

        // Increment the fractional counter
        if (frac_counter < 16'hFFFF) begin
            frac_counter <= frac_counter + 1;
        end else begin
            frac_counter <= 0; // Reset fractional counter
        end
    end
end

endmodule

