module fractional_n_pll(
    input wire clk,
    input wire rst,
    input wire [3:0] divider,
    output reg out_clk
);
    reg [3:0] counter;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 0;
            out_clk <= 0;
        end else begin
            if (counter == divider) begin
                out_clk <= ~out_clk;
                counter <= 0;
            end else begin
                counter <= counter + 1;
            end
        end
    end
endmodule

