module divider_4bit (  
    input clk,  
    input start,  
    input [3:0] numerator,  
    input [3:0] denominator,  
    output reg [3:0] quotient,  
    output reg [3:0] remainder,  
    output reg done  
);  
    reg [3:0] num;  
    reg [3:0] denom;  
    reg [3:0] temp_quotient;  
    reg [2:0] count;  
    reg state;  

    always @(posedge clk) begin  
        if (start) begin  
            num <= numerator;  
            denom <= denominator;  
            temp_quotient <= 4'b0000;  
            remainder <= numerator;  
            count <= 4;  
            done <= 0;  
            state <= 1;  
        end  
        else if (state) begin  
            if (count > 0) begin  
                remainder <= remainder << 1;  
                remainder[0] <= num[3];  
                temp_quotient <= temp_quotient << 1;  

                if (remainder >= denom) begin  
                    remainder <= remainder - denom;  
                    temp_quotient[0] <= 1;  
                end  
                num <= num << 1;  
                count <= count - 1;  
            end else begin  
                quotient <= temp_quotient;  
                done <= 1;  
                state <= 0;  
            end  
        end  
    end  
endmodule

