module deserializer(
    input wire clk,
    input wire reset,
    input wire serial_in,
    output reg [7:0] parallel_out,
    output reg data_ready
);
    reg [2:0] bit_count; // 3 bits can count up to 8
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            bit_count <= 3'b000;
            parallel_out <= 8'b00000000;
            data_ready <= 1'b0;
        end else if (bit_count < 3'b111) begin
            parallel_out <= {parallel_out[6:0], serial_in}; // Shift left and add new bit
            bit_count <= bit_count + 1;
            data_ready <= 1'b0;
        end else begin
            data_ready <= 1'b1; // Data ready after 8 bits
        end
    end
endmodule

