module ethernet_mac_controller (
    input wire clk,
    input wire reset,
    input wire START_RECEIVE,
    input wire START_TRANSMIT,
    input wire ERROR_SIGNAL,
    output reg [1:0] state
);

    // State encoding
    parameter IDLE = 2'b00;
    parameter RECEIVE = 2'b01;
    parameter TRANSMIT = 2'b10;
    parameter ERROR = 2'b11;

    // State transition
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (START_RECEIVE) begin
                        state <= RECEIVE;
                    end else if (START_TRANSMIT) begin
                        state <= TRANSMIT;
                    end
                end
                RECEIVE: begin
                    if (ERROR_SIGNAL) begin
                        state <= ERROR;
                    end else begin
                        // stay in RECEIVE state
                    end
                end
                TRANSMIT: begin
                    if (ERROR_SIGNAL) begin
                        state <= ERROR;
                    end else begin
                        // stay in TRANSMIT state
                    end
                end
                ERROR: begin
                    // Reset state to IDLE on error resolution
                    if (~ERROR_SIGNAL) begin
                        state <= IDLE;
                    end
                end
            endcase
        end
    end
endmodule

