module hmac (
    input clk,
    input reset,
    input start,
    input [127:0] key, // 128-bit key
    input [127:0] message, // 128-bit message
    output reg [255:0] hmac_output, // 256-bit HMAC output
    output reg done
);
    reg [1:0] state;
    localparam IDLE = 2'b00, PROCESS = 2'b01, OUTPUT = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            hmac_output <= 256'b0;
            done <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        // Initialize HMAC processing
                        // This is a simplified process, actual computation should be done
                        hmac_output <= {key, message}; // Simplified for illustration
                        state <= PROCESS;
                    end
                end
                PROCESS: begin
                    // Normally would call a hash function here
                    // For simplicity, we'll assume it's directly the concatenation
                    done <= 1;
                    state <= OUTPUT;
                end
                OUTPUT: begin
                    // HMAC is ready
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

module restoring_divider(
    input clk,
    input reset,
    input start,
    input [4:0] dividend,
    input [2:0] divisor,
    output reg [4:0] quotient,
    output reg [4:0] remainder,
    output reg done
);
    reg [4:0] temp_dividend;
    reg [2:0] count;
    reg in_progress;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            quotient <= 5'b0;
            remainder <= 5'b0;
            count <= 3'b0;
            in_progress <= 1'b0;
            done <= 1'b0;
        end else if (start && !in_progress) begin
            temp_dividend <= dividend;
            quotient <= 5'b0;
            remainder <= 5'b0;
            count <= 3'b101; // 5 iterations for 5-bit dividend
            in_progress <= 1'b1;
            done <= 1'b0;
        end else if (in_progress) begin
            remainder <= {remainder[3:0], temp_dividend[4]};
            temp_dividend <= {temp_dividend[3:0], 1'b0};

            if (remainder >= {2'b00, divisor}) begin
                remainder <= remainder - {2'b00, divisor};
                quotient <= {quotient[3:0], 1'b1};
            end else begin
                quotient <= {quotient[3:0], 1'b0};
            end

            count <= count - 1;
            if (count == 0) begin
                in_progress <= 1'b0;
                done <= 1'b1;
            end
        end
    end
endmodule

