module iir_filter(  
    input clk,  
    input reset,  
    input [15:0] x_in,  
    output reg [15:0] y_out  
);  
    // Filter coefficients (example values)  
    reg signed [15:0] b0 = 16'h1;  
    reg signed [15:0] b1 = 16'h1;  
    reg signed [15:0] b2 = 16'h1;  
    reg signed [15:0] b3 = 16'h1;  
    reg signed [15:0] b4 = 16'h1;  
    reg signed [15:0] a1 = 16'h1;  
    reg signed [15:0] a2 = 16'h1;  
    reg signed [15:0] a3 = 16'h1;  
    reg signed [15:0] a4 = 16'h1;  

    // Internal states for the filter  
    reg signed [15:0] x [0:4];  
    reg signed [15:0] y [0:4];  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            // Reset states  
            y_out <= 16'h0;  
            x[0] <= 16'h0;  
            x[1] <= 16'h0;  
            x[2] <= 16'h0;  
            x[3] <= 16'h0;  
            x[4] <= 16'h0;  
            y[0] <= 16'h0;  
            y[1] <= 16'h0;  
            y[2] <= 16'h0;  
            y[3] <= 16'h0;  
            y[4] <= 16'h0;  
        end else begin  
            // Shift input samples  
            x[4] <= x[3];  
            x[3] <= x[2];  
            x[2] <= x[1];  
            x[1] <= x[0];  
            x[0] <= x_in;  

            // Calculate output sample  
            y_out <= (b0 * x[0] + b1 * x[1] + b2 * x[2] + b3 * x[3] + b4 * x[4]  
                     - a1 * y[1] - a2 * y[2] - a3 * y[3] - a4 * y[4]) >> 15;  

            // Shift output samples  
            y[4] <= y[3];  
            y[3] <= y[2];  
            y[2] <= y[1];  
            y[1] <= y[0];  
            y[0] <= y_out;  
        end  
    end  
endmodule

