module dma_controller(  
    input clk,  
    input rst_n,  
    input [3:0] req,      // Request from 4 channels  
    output reg [3:0] ack, // Acknowledgment to 4 channels  
    output reg busy       // DMA is busy  
);  
    reg [1:0] state;  
    reg [1:0] next_state;  
    reg [1:0] active_channel;  

    parameter IDLE = 2'b00, GRANT = 2'b01, TRANSFER = 2'b10;  

    always @(posedge clk or negedge rst_n) begin  
        if (!rst_n)  
            state <= IDLE;  
        else  
            state <= next_state;  
    end  

    always @(*) begin  
        case (state)  
            IDLE: begin  
                if (req != 4'b0000) begin  
                    active_channel = req[3] ? 3 : (req[2] ? 2 : (req[1] ? 1 : 0));  
                    next_state = GRANT;  
                end else  
                    next_state = IDLE;  
                busy = 0;  
            end  
            GRANT: begin  
                ack = 4'b0000;  
                ack[active_channel] = 1;  
                next_state = TRANSFER;  
                busy = 1;  
            end  
            TRANSFER: begin  
                ack = 4'b0000;  
                // Assuming transfer is instant for simplicity  
                next_state = IDLE;  
                busy = 0;  
            end  
            default: begin  
                next_state = IDLE;  
                busy = 0;  
            end  
        endcase  
    end  
endmodule

