    input [7:0] A,  
    input [7:0] B,  
    output reg [7:0] result  
);  
    reg [7:0] stage1_instr;  
    reg [7:0] stage2_A, stage2_B;  
    reg [7:0] stage3_sum;  
    reg [7:0] stage4_mem;  
    reg [7:0] stage5_write;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            stage1_instr <= 8'd0;  
            stage2_A <= 8'd0;  
            stage2_B <= 8'd0;  
            stage3_sum <= 8'd0;  
            stage4_mem <= 8'd0;  
            stage5_write <= 8'd0;  
            result <= 8'd0;  
        end else begin  
            // Stage 1: Instruction Fetch  
            stage1_instr <= A + B;  

            // Stage 2: Decode  
            stage2_A <= A;  
            stage2_B <= B;  

            // Stage 3: Execute  
            stage3_sum <= stage2_A + stage2_B;  

            // Stage 4: Memory Access (not used in this simple example)  
            stage4_mem <= stage3_sum;  

            // Stage 5: Write-Back  
            stage5_write <= stage4_mem;  
            result <= stage5_write;  
        end  
    end  
endmodule

