module UART_Controller (
    input wire clk,
    input wire rst,
    input wire [7:0] data_in,
    input wire send,
    output reg tx,
    output reg [7:0] data_out,
    output reg received
);

    parameter BAUD_RATE = 9600;
    parameter CLOCK_FREQ = 50000000; // 50 MHz
    parameter CLOCK_DIV = CLOCK_FREQ / BAUD_RATE;

    reg [3:0] bit_count;
    reg [9:0] tx_data;
    reg [11:0] clk_count;
    reg transmitting;
    reg receiving;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx <= 1'b1; // idle state
            bit_count <= 0;
            clk_count <= 0;
            transmitting <= 0;
            receiving <= 0;
            data_out <= 0;
            received <= 0;
        end else begin
            if (send && !transmitting) begin
                tx_data <= {1'b1, data_in, 1'b0}; // start bit + data + stop bit
                transmitting <= 1;
                bit_count <= 0;
                clk_count <= 0;
            end

            if (transmitting) begin
                clk_count <= clk_count + 1;
                if (clk_count >= CLOCK_DIV) begin
                    clk_count <= 0;
                    tx <= tx_data[bit_count];
                    bit_count <= bit_count + 1;
                    if (bit_count == 10) begin
                        transmitting <= 0;
                        bit_count <= 0;
                    end
                end
            end

            // Simulate receiving data
            if (receiving) begin
                // For simulation, let's say we receive data after some cycles
                // In a real design, this would be an external input
                // Here we just set it for testing purposes
                data_out <= 8'hAA; // arbitrary data
                received <= 1;
            end
        end
    end
endmodule

