code:
module stop_and_wait(
    input wire clk,
    input wire reset,
    input wire send,
    output reg ack,
    output reg packet_sent,
    output reg [1:0] state // 0: WAITING, 1: SENDING
);
    parameter WAITING = 2'b00, SENDING = 2'b01;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= WAITING;
            packet_sent <= 0;
            ack <= 0;
        end else begin
            case (state)
                WAITING: begin
                    packet_sent <= 0;
                    if (send) begin
                        state <= SENDING;
                    end
                end
                SENDING: begin
                    packet_sent <= 1;
                    ack <= 0; // Prepare to wait for ACK
                    state <= WAITING; // Move back to WAITING after sending
                end
                default: state <= WAITING;
            endcase
        end
    end
endmodule

